// Mana Maze
// status: planned
// requires: earlier objects LastCast
// Players can't cast spells that share a color with the spell most recently cast this turn.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_0_rule(q: &dyn Query, asker: &Asker, player: PlayerId, spell: ObjectId) -> bool { !(true && (planned_value!("earlier objects LastCast", Vec::<ObjectId>::new() => q.acted_on(asker, Acted::LastCast))).first().copied().is_some_and(|o: ObjectId| { let (a, b) = (&q.chars(spell), &q.chars(o)); a.colors.intersects(b.colors) })) }

